      ro: ["Altitudine de cultivare între 1.200 și 1.600 metri", "Predomină soiurile Arabica (Typica, Bourbon)", "Cultura la umbră protejează calitatea solului", "Zaruma este pe lista indicativă a Patrimoniului UNESCO", "Cultivarea cafelei este stabilită din secolul al XIX-lea", "Specialitate locală: cafea servită cu 'Tigrillo'"],
      en: ["Cultivation altitude between 1,200 and 1,600 meters", "Predominantly Arabica varieties (Typica, Bourbon)", "Traditional shade-growing protects the soil", "Zaruma is a candidate for UNESCO World Heritage status", "Coffee farming has been established since the 19th century", "Local specialty: coffee served with 'Tigrillo'"],
      es: ["Altitud de cultivo entre 1.200 y 1.600 metros.", "Predominan las variedades arábica (Typica, Bourbon).", "El cultivo tradicional bajo sombra protege el suelo.", "Zaruma forma parte de la lista del Patrimonio Mundial de la UNESCO.", "El cultivo del café está establecido desde el siglo XIX.", "Especialidad local: café servido con 'Tigrillo'."],
      pt: ["Altitude de cultivo entre 1.200 e 1.600 metros.", "Predominantemente variedades Arábica (Typica, Bourbon).", "A economia de sombra tradicional protege o solo.", "Zaruma faz parte da lista do Património Mundial da UNESCO.", "O cultivo do café está estabelecido desde o século XIX.", "Especialidade local: café servido com 'Tigrillo'."],
