      hu: ["1959-ben alapították (Charles Darwin Alapítvány)", "Székhelye Puerto Ayora, Santa Cruz sziget", "Itt élt 'Magányos George' 2012-ig", "Az óriásteknősök 11 különböző alfaját tenyésztik", "Több mint 100 tudóst és önkéntest foglalkoztat", "Fő cél az invazív fajok, pl. kecskék és patkányok visszaszorítása"],
      ro: ["Înființată în 1959 (Fundația Charles Darwin)", "Sediul în Puerto Ayora, Insula Santa Cruz", "Locuința lui 'Lonesome George' până în 2012", "Creșterea a 11 subspecii diferite de țestoase gigantice", "Angajează peste 100 de cercetători și voluntari", "Focus pe controlul speciilor invazive precum caprele și șobolanii"],
      en: ["Established in 1959 by the Charles Darwin Foundation", "Located in Puerto Ayora on Santa Cruz Island", "Home to 'Lonesome George' until 2012", "Rears 11 different subspecies of giant tortoises", "Employs over 100 scientists and volunteers", "Focuses on controlling invasive species like goats and rats"],
      es: ["Fundada en 1959 (Fundación Charles Darwin).", "Sede en Puerto Ayora, isla Santa Cruz.", "Hogar del 'Solitario George' hasta 2012.", "Cría de 11 subespecies diferentes de tortuga gigante.", "Emplea a más de 100 científicos y voluntarios.", "Centrada en el control de especies invasoras como cabras y ratas."],
      pt: ["Fundada em 1959 (Fundação Charles Darwin).", "Sede em Puerto Ayora, ilha de Santa Cruz.", "Lar de 'George Solitário' até 2012.", "Criação de 11 subespécies diferentes de tartaruga gigante.", "Emprega mais de 100 cientistas e voluntários.", "Foco no controle de espécies invasoras, como cabras e ratos."],
      fr: ["Fondée en 1959 (Fondation Charles Darwin).", "Siège à Puerto Ayora, sur l'île de Santa Cruz.", "Demeure de 'George le Solitaire' jusqu'en 2012.", "Élevage de 11 sous-espèces différentes de tortues géantes.", "Emploie plus de 100 scientifiques et bénévoles.", "Axée sur le contrôle des espèces envahissantes comme les chèvres et les rats."],
